const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const templates=[['Chief of Staff','Coordinate your AI team','Break objectives into clear plans, prepare useful drafts and identify decisions for human approval.'],['Research Agent','Research and insights','Analyze supplied information, distinguish evidence from assumptions, and prepare concise research briefs.'],['Sales Outreach','Personalized outreach','Draft relevant, thoughtful outreach sequences using only verified facts supplied by the user.'],['Growth Marketer','Content and campaigns','Create useful campaign plans and social content tailored to the user’s business and audience.'],['Customer Support','Customer experience','Draft clear, empathetic replies using supplied product documentation. Escalate uncertainty.']];
const catalog=[['Gmail','Communication','Email drafts, conversations and follow-ups','M'],['Notion','Productivity','Knowledge, documents and project notes','N'],['YouTube','Social media','Video content and channel insights','▶'],['Google Ads','Advertising','Campaigns, keywords and performance','A'],['Instagram','Social media','Content planning and publishing','◎'],['Facebook','Social media','Pages, posts and community management','f'],['LinkedIn','Social media','Company content and professional outreach','in'],['X / Twitter','Social media','Posts and brand conversations','𝕏'],['TikTok','Social media','Short-form content and channel planning','♪'],['WhatsApp Business','Communication','Customer messages and conversations','◉'],['Slack','Communication','Team conversations and notifications','#'],['Outlook','Communication','Email and calendar workflows','O'],['Google Drive','Productivity','Documents and shared files','△'],['Google Calendar','Productivity','Meetings and schedules','31'],['Google Sheets','Productivity','Reports, lists and structured data','▤'],['HubSpot','Sales & CRM','Contacts, deals and pipeline','H'],['Salesforce','Sales & CRM','Customer records and opportunities','S'],['Apollo','Sales & CRM','Prospecting and contact enrichment','a'],['WordPress','Productivity','Website content and articles','W'],['Meta Ads','Advertising','Paid social campaigns and insights','∞'],['Google Analytics','Advertising','Website traffic and conversion reports','▥'],['Zendesk','Communication','Support tickets and customer service','Z']];
const platformSlugs=["gmail", "notion", "youtube", "googleads", "instagram", "facebook", "linkedin", "x", "tiktok", "whatsapp", "slack", "microsoftoutlook", "googledrive", "googlecalendar", "googlesheets", "hubspot", "salesforce", "apollo", "wordpress", "meta", "googleanalytics", "zendesk"];
function platformIcon(name){const slug=platformSlugs[catalog.findIndex(c=>c[0]===name)];return `<img src="/assets/platforms/${slug}.svg" alt="" width="28" height="28">`}
let state,mode='api',page='app',aid='1',tab='chat',category='All',busy=false;
const iconPaths={card:'M3 5h18v14H3zM3 10h18M7 15h3',overview:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',plus:'M12 5v14M5 12h14',menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M6 18 18 6',arrow:'M12 19V5m-6 6 6-6 6 6',back:'M19 12H5m6-6-6 6 6 6',file:'M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9zM14 3v6h6M8 13h8M8 17h5',plug:'M8 3v4m8-4v4M6 7h12v3a6 6 0 0 1-12 0V7zm6 9v5',user:'M20 21v-2a7 7 0 0 0-14 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',copy:'M9 9h11v12H9zM15 9V3H3v12h6',check:'m5 12 4 4L19 6',chevron:'m9 5 7 7-7 7',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',edit:'m15 5 4 4M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15v5z'};
function uiIcon(name){return `<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.file}"/></svg>`}
const avatar=a=>`<span class="mascot" style="--ax:${[-5,-42,-82,-118,-21,-61,-97,-5][a.avatar]??-5}px;--ay:${[-7,-6,-5,-13,-37,-36,-37,-64][a.avatar]??-7}px" aria-hidden="true"></span>`;
function formattedText(text){
 const inline=t=>esc(t).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
 return String(text).split(/(```[\s\S]*?```)/g).map(part=>{
  if(part.startsWith('```'))return '<pre><code>'+esc(part.slice(3,-3).replace(/^[a-zA-Z0-9_-]*\n/,''))+'</code></pre>';
  return part.split(/\n\s*\n/).filter(t=>t.trim()).map(block=>{
   const lines=block.trim().split('\n');
   if(lines.every(l=>/^\s*[-*] /.test(l)))return '<ul>'+lines.map(l=>'<li>'+inline(l.replace(/^\s*[-*] /,''))+'</li>').join('')+'</ul>';
   if(lines.every(l=>/^\s*\d+\. /.test(l)))return '<ol>'+lines.map(l=>'<li>'+inline(l.replace(/^\s*\d+\. /,''))+'</li>').join('')+'</ol>';
   return lines.map(l=>/^https?:\/\/[^\s<>]+$/.test(l)?'<p><a href="'+esc(l)+'" target="_blank" rel="noopener noreferrer">'+esc(l)+'</a></p>':/^#{1,3} /.test(l)?'<h3>'+inline(l.replace(/^#{1,3} /,''))+'</h3>':'<p>'+inline(l)+'</p>').join('');
  }).join('');
 }).join('');
}
async function copyMessage(index,button){try{await navigator.clipboard.writeText(state.messages[index].content);button.innerHTML=uiIcon('check');button.setAttribute('aria-label','Copied');setTimeout(()=>{button.innerHTML=uiIcon('copy');button.setAttribute('aria-label','Copy response')},1800)}catch{toast('Copy unavailable. Select the response text to copy it.')}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
function save(){if(mode==='demo')localStorage.setItem('bainbot-workfolk-reference-v2',JSON.stringify(state))}
async function api(path,body,method='POST'){const r=await fetch('/api'+path,{method:body===undefined?'GET':method,headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let d;try{d=await r.json()}catch{throw Error('The backend returned an unexpected response')}if(!r.ok){if(r.status===401&&state&&path!=='/login'){clearPrivateState();history.replaceState(null,'','/login');authPage('login')}throw Error(typeof d.detail==='string'?d.detail:'Please check the form and try again')}return d}
async function refresh(){if(mode==='api')state=await api('/state');else save();render()}
function route(){normalizeWorkspaceURL();if(location.pathname==='/join')return auth(false,new URLSearchParams(location.search).get('token')||'');if(authRoute())return authPage(authPath());if(!state){history.replaceState(null,'','/login');return authPage('login')}taskFilter='all';taskQuery='';page=workspacePath()||'app';const params=new URLSearchParams(location.search);aid=(page==='agent'?params.get('id'):params.get('agent'))||state.agents[0]?.id||'';tab=params.get('tab')==='tasks'?'tasks':'chat';render()}
const owner=()=>state.me.role==='owner';
function canOperate(id){return owner()||state.grants.some(g=>g.user_id===state.me.id&&g.agent_id===id&&g.permission==='operator')}
function shell(content){return `<div class="shell"><aside class="sidebar"><div class="brand-row"><a href="/app?agent=${aid}" class="brand">Bainbot<span>YOUR AI TEAM</span></a>${owner()?`<a class="add-agent" href="/create" aria-label="Create agent">${uiIcon('plus')}</a>`:''}<button class="bare mobile" onclick="$('.sidebar').classList.remove('open')" aria-label="Close menu">${uiIcon('close')}</button></div><input id="teammate-search" placeholder="Search agents…" aria-label="Find a teammate"><div class="row between section-label"><span>Teammates</span><span class="agent-count">${state.agents.length} agents</span></div><div class="teammate-list">${state.agents.map(a=>`<a class="agent-nav ${a.id===aid&&['app','agent'].includes(page)?'active':''}" href="/app?agent=${a.id}" data-name="${esc(a.name.toLowerCase())}">${avatar(a)}<div class="agent-info"><div class="row between"><strong>${esc(a.name)}</strong></div><span class="sub">${a.status==='paused'?'Paused':esc(state.messages.filter(m=>m.agent_id===a.id).at(-1)?.content||a.role)}</span></div></a>`).join('')}</div><div class="foot"><a href="/overview" class="connections-link ${page==='overview'?'current':''}">${uiIcon('overview')}<span>Overview</span></a><a href="/connections" class="connections-link ${page==='connections'?'current':''}">${uiIcon('plug')}<span>Connections</span></a><a href="/profile" class="profile-button"><span class="owner-name">${uiIcon('user')} ${esc(state.me.name)}</span><small>${owner()?'Owner':'Member'}</small></a></div></aside><main>${page==='app'?'':`<header class="topbar"><div class="row"><button class="bare mobile" onclick="$('.sidebar').classList.add('open')" aria-label="Open menu">${uiIcon('menu')}</button><a href="/app?agent=${aid}">${uiIcon('back')} Back to workspace</a></div><span>${({overview:'Overview',create:'Create agent',agent:'Agent profile',connections:'Connections',profile:'Profile & team'})[page]||''}</span></header>`}${content}</main></div>`}
function intro(title,sub,action=''){return `<div class="intro"><div class="row between"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div></div>`}
function chat(){let a=state.agents.find(a=>a.id===aid);if(!a)return `<div class="content">${intro('Your workspace','Create an agent to get started.','<a href="/create">Create an agent</a>')}</div>`;return `<div class="chat-layout"><div class="chat-head row between"><div class="row chat-identity"><button class="bare mobile" onclick="$('.sidebar').classList.add('open')" aria-label="Open menu">${uiIcon('menu')}</button>${avatar(a)}<h3>${esc(a.name)}</h3><a href="/agent?id=${a.id}"><button>View details</button></a>${owner()?`<a href="/agent?id=${a.id}" onclick="sessionStorage.setItem('focus-agent-edit','yes')"><button>Edit agent</button></a>`:''}</div><div class="tabs"><button class="${tab==='chat'?'active':''}" onclick="navigate('/app?agent='+encodeURIComponent(aid))">Chat</button><button class="${tab==='tasks'?'active':''}" onclick="navigate('/app?agent='+encodeURIComponent(aid)+'&tab=tasks')">Tasks <small>${state.tasks.filter(t=>t.agent_id===aid).length}</small></button></div></div><div class="chat-body">${tab==='chat'?conversation(a):tasks(a)}</div>${tab==='chat'?`${chatComposer(a)}<div class="mode-note">${mode==='demo'?'Demo workspace · No actions sent':!canOperate(a.id)?'View-only access':a.status==='paused'?'Agent paused':'Free beta · Research and writing · Review before use'}</div>`:''}</div>`}
function conversation(a){const ms=state.messages.map((m,index)=>({...m,index})).filter(m=>m.agent_id===aid);const pending=state.tasks.find(t=>t.agent_id===aid&&t.status==='pending');const card=pending?`<button class="draft-link" onclick="review('${pending.id}')"><span class="draft-file">${uiIcon('file')}</span><div><strong>${esc(pending.title)}</strong><small>Draft · Ready to review</small></div>${uiIcon('chevron')}</button>`:'';return `<div class="conversation-column"><div class="date">${mode==='demo'?'Sample conversation':'Conversation'}</div>${ms.length?ms.map((m,i)=>`<article class="message ${m.role==='user'?'user':'assistant'}">${m.role==='assistant'?`<div class="response-label">${avatar(a)}<span>${esc(a.name)}</span></div>`:''}<div class="bubble">${m.role==='assistant'?formattedText(m.content):esc(m.content)}${attachmentMarkup(m.attachments)}</div>${m.role==='assistant'?`<div class="response-actions"><button class="bare" onclick="copyMessage(${m.index},this)" aria-label="Copy response" title="Copy response">${uiIcon('copy')}</button></div>`:''}</article>${i===1?card:''}`).join(''):`<div class="chat-empty">${avatar(a)}<h1>How can I help?</h1><p class="muted">Give ${esc(a.name)} a task to get started.</p><div class="suggestions">${['Plan a campaign','Draft a content plan','Prioritize my work'].map(s=>`<button onclick="prefill(this.textContent)">${s}</button>`).join('')}</div></div>`}${ms.length<2?card:''}</div>`}
const actionTypes=[['draft','Create drafts','Write content and prepare documents.'],['research','Research & read','Find information and read connected data.'],['email','Send emails & messages','Contact people through connected accounts.'],['publish','Publish content','Post or schedule public content.'],['update','Update records','Change documents, CRM data, or campaigns.'],['spend','Spend money','Start paid campaigns or make purchases.'],['delete','Delete data','Remove records or content.']];
function permissionFor(a,key){return a.action_permissions?.[key]||(key==='draft'?'allow':'approval')}
function effectiveRule(a,key){const r=permissionFor(a,key);return r==='block'?'block':a.approval_mode==='direct'?r:'approval'}
function actionControls(a={}){return `<div class="action-policy-panel" ${a.approval_mode==='direct'?'':'hidden'}><div class="row between"><h3>Automatic actions</h3><span class="tag">Per action</span></div><p class="hint">Choose what this agent can do on its own. Other actions still need approval.</p>${actionTypes.map(([key,label,desc])=>`<div class="policy-row"><div><strong>${label}</strong><small>${desc}</small></div><select name="policy_${key}" aria-label="${label} permission" ${!owner()?'disabled':''}>${[['allow','Run directly'],['approval','Ask for approval'],['block','Not allowed']].map(([v,l])=>`<option value="${v}" ${permissionFor(a,key)===v?'selected':''}>${l}</option>`).join('')}</select></div>`).join('')}<p class="hint">These rules do not grant access to accounts or tools. Live actions require a connected executor.</p></div>`}
function syncExecution(form){const panel=form.querySelector('.action-policy-panel');if(panel)panel.hidden=form.elements.approval_mode.value!=='direct'}
let taskFilter='all',taskRange='30',taskQuery='';
const taskStatuses={running:['In progress','blue'],queued:['Queued','neutral'],pending:['Pending approval','amber'],completed:['Completed','green'],failed:['Failed','red'],approved:['Approved · Not executed','neutral'],ready:['Ready · Not executed','neutral'],rejected:['Held back','neutral']};
function statusBadge(t){const [label,color]=taskStatuses[t.status]||[t.status,'neutral'];return `<span class="task-status ${color}"><i></i>${esc(label)}</span>`}
function taskDate(n){return n?new Date(n*1000).toLocaleDateString(undefined,{month:'short',day:'numeric'}):'—'}
function taskDuration(n){return n<60?Math.round(n)+' sec':n<3600?Math.round(n/60)+' min':(n/3600).toFixed(1)+' hr'}
function agentMetrics(ts){const done=ts.filter(t=>t.status==='completed'),failed=ts.filter(t=>t.status==='failed'),timed=done.filter(t=>Number.isFinite(t.started)&&Number.isFinite(t.finished)&&t.finished>=t.started);return {done:done.length,ongoing:ts.filter(t=>['running','queued'].includes(t.status)).length,pending:ts.filter(t=>t.status==='pending').length,success:done.length+failed.length?Math.round(done.length/(done.length+failed.length)*100):null,duration:timed.length?timed.reduce((n,t)=>n+t.finished-t.started,0)/timed.length:null}}
function filteredAgentTasks(){const cutoff=taskRange==='all'?0:Date.now()/1000-Number(taskRange)*86400;return state.tasks.filter(t=>t.agent_id===aid&&t.created>=cutoff).sort((a,b)=>b.created-a.created)}
function taskMatches(t){return (taskFilter==='all'||taskFilter==='ongoing'&&['running','queued'].includes(t.status)||taskFilter===t.status)&&t.title.toLowerCase().includes(taskQuery.toLowerCase())}
function taskRows(ts){const visible=ts.filter(taskMatches);return visible.length?visible.map(t=>`<button class="task-record" onclick="review('${t.id}')"><span class="record-symbol">${uiIcon(t.status==='completed'?'check':'file')}</span><div class="record-main"><strong>${esc(t.title)}</strong><span>${esc(t.summary||({running:'Working on this task',queued:'Waiting to start',pending:'Your review is needed',completed:'Result available',failed:'Open details to see the issue',approved:'Approved; no action executed',ready:'Ready; no action executed',rejected:'Stopped at review'}[t.status]||'Open task details'))}</span>${t.status==='running'&&Number.isFinite(t.progress)?`<div class="task-progress" aria-label="${Math.round(t.progress)} percent"><i style="width:${Math.min(100,Math.max(0,t.progress))}%"></i></div>`:''}</div><div class="record-meta">${statusBadge(t)}<small>${taskDate(t.created)}${t.sample?' · Sample':''}</small></div>${uiIcon('chevron')}</button>`).join(''):'<div class="empty task-empty"><h3>No tasks here yet</h3><p>Tasks will appear as this agent works. Try another filter or start a conversation.</p></div>'}
function taskFilterControls(ts){const counts={all:ts.length,ongoing:ts.filter(t=>['running','queued'].includes(t.status)).length,pending:ts.filter(t=>t.status==='pending').length,completed:ts.filter(t=>t.status==='completed').length,failed:ts.filter(t=>t.status==='failed').length};return [['all','All tasks'],['ongoing','Ongoing'],['pending','Pending approval'],['completed','Completed'],['failed','Failed']].map(([key,label])=>`<button class="${taskFilter===key?'active':''}" onclick="taskFilter='${key}';render()">${label}<span>${counts[key]}</span></button>`).join('')}
function tasks(a){const ts=filteredAgentTasks(),m=agentMetrics(ts);return `<section class="agent-tasks"><div class="row between task-page-title"><div><h2>Tasks & performance</h2><p>Track ${esc(a.name)}’s work, results, and approvals.</p></div><select class="task-range" aria-label="Performance period" onchange="taskRange=this.value;render()">${[['7','Last 7 days'],['30','Last 30 days'],['all','All time']].map(([v,l])=>`<option value="${v}" ${taskRange===v?'selected':''}>${l}</option>`).join('')}</select></div>${mode==='demo'?'<div class="sample-caption">Sample activity · Preview data only. No live tasks are running.</div>':''}<div class="performance-grid">${[['Completed',m.done,'Finished tasks'],['Ongoing',m.ongoing,'In progress + queued'],['Pending approval',m.pending,'Waiting for review'],['Success rate',m.success===null?'—':m.success+'%','Completed ÷ completed + failed'],['Avg. completion',m.duration===null?'—':taskDuration(m.duration),'Timed completed tasks']].map(([label,value,note])=>`<div class="performance-stat"><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`).join('')}</div><div class="task-toolbar"><div class="task-filters">${taskFilterControls(ts)}</div><input class="task-search" value="${esc(taskQuery)}" aria-label="Search agent tasks" placeholder="Search tasks…" oninput="taskQuery=this.value;$('#task-records').innerHTML=taskRows(filteredAgentTasks())"></div><div class="task-records" id="task-records">${taskRows(ts)}</div><p class="metrics-note">Metrics use tasks created in the selected period. Approved and ready drafts are not counted as completed.</p></section>`}
let overviewRange='30',overviewQueue='pending';
function workspaceTasks(){const ids=new Set(state.agents.map(a=>a.id));const cutoff=overviewRange==='all'?0:Date.now()/1000-Number(overviewRange)*86400;return state.tasks.filter(t=>ids.has(t.agent_id)&&t.created>=cutoff).sort((a,b)=>b.created-a.created)}
function workspaceOverview(){const ts=workspaceTasks(),m=agentMetrics(ts),failed=ts.filter(t=>t.status==='failed').length,active=state.agents.filter(a=>a.status==='active').length,paused=state.agents.length-active;const queue=ts.filter(t=>overviewQueue==='ongoing'?['running','queued'].includes(t.status):t.status===overviewQueue);const taskLink=t=>`<button class="overview-work-item" onclick="review('${t.id}')"><span class="record-symbol">${uiIcon(t.status==='completed'?'check':'file')}</span><span class="overview-work-text"><strong>${esc(t.title)}</strong><small>${esc(state.agents.find(a=>a.id===t.agent_id)?.name||'Agent')} · ${taskDate(t.created)}</small></span>${statusBadge(t)}${uiIcon('chevron')}</button>`;return `<div class="content workspace-overview">${intro('Overview','Your AI team’s work, in one place.',`<select class="task-range" aria-label="Overview period" onchange="overviewRange=this.value;render()">${[['7','Last 7 days'],['30','Last 30 days'],['all','All time']].map(([v,l])=>`<option value="${v}" ${overviewRange===v?'selected':''}>${l}</option>`).join('')}</select>`)}${mode==='demo'?'<div class="sample-caption overview-sample">Sample workspace · These tasks illustrate the dashboard. No live work is running.</div>':''}${!owner()?'<p class="hint">Showing only agents and tasks you have access to.</p>':''}<div class="overview-stats">${[['Active agents',active,paused+' paused · '+state.agents.length+' total'],['Ongoing tasks',m.ongoing,'In progress + queued'],['Pending approval',m.pending,'Waiting for your review'],['Completed',m.done,'Finished tasks'],['Failed',failed,'Needs attention']].map(([l,v,n])=>`<div class="performance-stat"><span>${l}</span><strong>${v}</strong><small>${n}</small></div>`).join('')}</div><div class="overview-columns"><section class="card overview-attention"><div class="row between"><div><h2>Needs attention</h2><p class="hint">Review work or check what’s holding it up.</p></div><span class="pill">${queue.length}</span></div><div class="task-filters overview-filters">${[['pending','Approvals',m.pending],['failed','Failed',failed],['ongoing','Ongoing',m.ongoing]].map(([key,label,n])=>`<button class="${overviewQueue===key?'active':''}" onclick="overviewQueue='${key}';render()">${label}<span>${n}</span></button>`).join('')}</div><div class="overview-queue">${queue.length?queue.map(taskLink).join(''):'<div class="empty"><h3>All clear here</h3><p>No tasks in this category for the selected period.</p></div>'}</div></section><section class="card overview-performance"><h2>Team performance</h2><p class="hint">Results for the selected period.</p><div class="overview-rate"><div><span>Success rate</span><strong>${m.success===null?'—':m.success+'%'}</strong></div><div><span>Avg. completion</span><strong>${m.duration===null?'—':taskDuration(m.duration)}</strong></div></div><div class="overview-distribution">${[['Completed',m.done,'done'],['Ongoing',m.ongoing,'work'],['Pending approval',m.pending,'review'],['Failed',failed,'error'],['Other',ts.length-m.done-m.ongoing-m.pending-failed,'other']].map(([l,n,c])=>`<div><div class="row between"><span>${l}</span><strong>${n}</strong></div><div class="distribution-track"><i class="${c}" style="width:${ts.length?n/ts.length*100:0}%"></i></div></div>`).join('')}</div><p class="hint metric-definition">Success rate = completed ÷ (completed + failed). Average time uses timed completed tasks only.</p></section></div><section class="card overview-team"><div class="row between"><div><h2>Your team</h2><p class="hint">See each agent’s workload and open its tasks.</p></div>${owner()?'<a href="/create"><button>+ Create agent</button></a>':''}</div><div class="table-wrap"><table><thead><tr><th>Agent</th><th>Status</th><th>Ongoing</th><th>Approvals</th><th>Completed</th><th>Success</th><th></th></tr></thead><tbody>${state.agents.map(a=>{const stats=agentMetrics(ts.filter(t=>t.agent_id===a.id));return `<tr><td><div class="row overview-agent">${avatar(a)}<span><strong>${esc(a.name)}</strong><small>${esc(a.role)}</small></span></div></td><td><span class="task-status ${a.status==='active'?'green':'neutral'}"><i></i>${a.status==='active'?'Active':'Paused'}</span></td><td>${stats.ongoing}</td><td>${stats.pending}</td><td>${stats.done}</td><td>${stats.success===null?'—':stats.success+'%'}</td><td><a class="agent-tasks-link" href="/app?agent=${a.id}&tab=tasks">View tasks ${uiIcon('chevron')}</a></td></tr>`}).join('')}</tbody></table>${state.agents.length?'':'<div class="empty">Create your first agent to build your team.</div>'}</div></section><section class="card overview-recent"><div class="row between"><div><h2>Recent tasks</h2><p class="hint">Latest tasks created across your team.</p></div><span class="pill">${Math.min(6,ts.length)} of ${ts.length}</span></div><div class="overview-recent-list">${ts.slice(0,6).map(taskLink).join('')||'<div class="empty">No tasks yet. Give an agent a task to get started.</div>'}</div></section><p class="metrics-note">Task metrics use tasks created in the selected period. Agent status is current. Approved and ready drafts are not completed work. “Other” includes approved, ready, and held-back drafts.</p></div>`}
function overview(a){const ts=state.tasks.filter(t=>t.agent_id===a.id);return `<h2>Activity</h2><p class="muted" style="margin:5px 0 25px">${mode==='demo'?'Sample workspace activity':'Your saved activity'} for ${esc(a.name)}.</p><div class="cards">${[['Drafts created',ts.length],['Awaiting review',ts.filter(t=>t.status==='pending').length],['Approved drafts',ts.filter(t=>t.status==='approved').length]].map(([l,n])=>`<div class="card"><small>${l}</small><div class="metric">${n}</div></div>`).join('')}</div><div class="card" style="margin-top:20px"><h3>Working boundaries</h3><div class="detail-row"><span>External actions</span><span>${a.approval_mode==='direct'?'Direct implementation':'Approval required'}</span></div><div class="detail-row"><span>Model</span><span>${esc(a.model||'Workspace default')}</span></div><div class="detail-row"><span>Status</span><span>${esc(a.status)}</span></div><p class="hint" style="margin-top:15px">This version generates and reviews drafts. Background scheduling and live tool execution are not enabled.</p></div>`}
function reportingName(a){return !a.reports_to||a.reports_to==='owner'?'Workspace owner':state.agents.find(x=>x.id===a.reports_to)?.name||'Assigned agent'}
function validManager(target,id){const seen=new Set([id]);while(target&&target!=='owner'){if(seen.has(target))return false;seen.add(target);const a=state.agents.find(x=>x.id===target);if(!a)return false;target=a.reports_to||'owner'}return true}
function workflowFields(a={}){return `<div class="workflow-settings"><label>Reports to<select name="reports_to" ${!owner()?'disabled':''}><option value="owner">Workspace owner</option>${state.agents.filter(x=>validManager(x.id,a.id)).map(x=>`<option value="${x.id}" ${a.reports_to===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><span class="hint">Choose the owner or a lead AI agent.</span></label><fieldset class="execution-options" ${!owner()?'disabled':''}><legend>Execution mode</legend><label class="execution-choice"><input type="radio" name="approval_mode" onchange="syncExecution(this.form)" value="approval" ${a.approval_mode!=='direct'?'checked':''}><span><strong>Approval before implementation</strong><small>Hold work for review before taking action.</small></span></label><label class="execution-choice"><input type="radio" name="approval_mode" onchange="syncExecution(this.form)" value="direct" ${a.approval_mode==='direct'?'checked':''}><span><strong>Direct implementation</strong><small>Skip the review step for supported actions.</small></span></label></fieldset>${actionControls(a)}<div class="hint">Sending and publishing are not available yet. Direct mode marks new drafts as ready; nothing is sent. Reporting lines do not change user permissions or enable automatic delegation.</div></div>`}
function create(){if(!owner())return '<div class="empty">Only the owner can create agents.</div>';return `<div class="content" style="max-width:980px">${intro('Create an agent','Choose a role and tell your agent what to do.')}<form id="agent-form"><div class="section-label" style="margin-left:0">Choose a template</div><div class="cards">${templates.slice(1,4).map((t,i)=>`<button type="button" class="template" onclick="useTemplate(${i+1},this)">${avatar({avatar:i+1})}<h3>${t[0]}</h3><small>${t[1]}</small></button>`).join('')}</div><section class="formsection"><h3>Agent details</h3><div class="formgrid"><label>Agent name<input name="name" placeholder="e.g. Growth Marketer" required maxlength="80"></label><label>Role<input name="role" placeholder="e.g. Content and campaigns" required maxlength="120"></label><label class="full">Instructions<textarea name="instructions" placeholder="Describe the work, your business, and your preferred tone…" required maxlength="8000"></textarea></label><label>AI model<input name="model" placeholder="Use workspace default"><div class="hint">Leave blank to use your workspace model.</div></label><label>Agent avatar<select name="avatar">${templates.map((t,i)=>`<option value="${i}">${['Blue','Lime','Gold','Coral','Lilac'][i]}</option>`).join('')}</select></label></div></section><section class="formsection"><h3>Reporting & approvals</h3>${workflowFields()}</section><div class="row between" style="margin-top:25px"><a href="/app">Cancel</a><button class="primary">Create agent</button></div></form></div>`}
function agentProfile(){const a=state.agents.find(a=>a.id===aid);if(!a)return '<div class="empty">Agent not found.</div>';return `<div class="content">${intro('Agent profile','Manage your agent’s role, instructions, and settings.',`<a href="/app?agent=${a.id}"><button>Open chat</button></a>`)}<div class="profile-hero row">${avatar(a)}<div><span class="tag">AI TEAMMATE</span><h1 style="margin-top:10px">${esc(a.name)}</h1><p class="muted">${esc(a.role)}</p></div></div><div class="split"><form id="edit-agent-form" class="card stack"><h2>Agent details</h2><label>Name<input name="name" value="${esc(a.name)}" required maxlength="80" ${!owner()?'disabled':''}></label><label>Role<input name="role" value="${esc(a.role)}" required maxlength="120" ${!owner()?'disabled':''}></label><label>Instructions<textarea name="instructions" required maxlength="8000" ${!owner()?'disabled':''}>${esc(a.instructions)}</textarea></label><label>Model<input name="model" value="${esc(a.model)}" placeholder="Workspace default" ${!owner()?'disabled':''}></label><h3>Reporting & approvals</h3>${workflowFields(a)}${owner()?'<button class="primary">Save changes</button>':''}</form><div class="stack" style="align-content:start"><div class="card"><h3>Agent status</h3><p class="muted" style="margin:12px 0;font-size:12px">${a.status==='active'?'Ready to work.':'Paused until you resume.'}</p>${owner()?`<button onclick="toggleAgent()">${a.status==='active'?'Pause agent':'Resume agent'}</button>`:''}</div><div class="card"><h3>Tools & connections</h3><p class="muted" style="font-size:12px;margin:12px 0">Browse the apps available for future connections.</p><a href="/connections"><button>Browse apps</button></a></div><div class="card"><h3>Approvals</h3><p class="muted" style="font-size:12px;margin-top:10px">${a.approval_mode==='direct'?'Direct mode · New drafts skip review. No external actions run yet.':'Approval required · New drafts wait for review.'}</p><div class="detail-row"><span>Reports to</span><strong>${esc(reportingName(a))}</strong></div><p class="hint">Applies to new tasks. Existing review decisions stay unchanged.</p></div></div></div></div>`}
function connections(){return `<div class="content">${intro('Connections','Bring your team’s tools into one workspace.')}<div class="row between"><input class="searchbox" id="connection-search" aria-label="Search connections" placeholder="⌕  Search apps…"><span class="pill">${catalog.length} apps</span></div><div class="filters">${['All','Communication','Social media','Productivity','Sales & CRM','Advertising'].map(c=>`<button class="${category===c?'active':''}" onclick="category='${c}';render()">${c}</button>`).join('')}</div><div class="card" style="margin:20px 0"><h3>Web research</h3><p class="hint">${state.capabilities?.search?'Available · Select Agent workflow or Search only in chat.':'Not configured · Configure TinyFish or Tavily in your server environment.'}</p><h3>AI writing & chat</h3><p class="hint">${state.capabilities?.chat?'Available · Send a normal message to your agent.':'Not configured · A separate model API is needed for writing and chat.'}</p></div><div class="notice" style="margin-bottom:24px">More integrations are coming. The apps below are not connected yet.</div><div class="connection-grid" id="connection-grid">${connectionCards('')}</div></div>`}
function connectionCards(q){return catalog.filter(c=>(category==='All'||c[1]===category)&&(c[0]+' '+c[2]).toLowerCase().includes(q.toLowerCase())).map(c=>`<div class="card connection"><div class="row between"><span class="logo">${platformIcon(c[0])}</span><span class="pill">Not connected</span></div><h3>${c[0]}</h3><p>${c[2]}</p><button onclick="connectionInfo('${c[0]}')">View details</button></div>`).join('')||'<div class="empty">No apps match your search.</div>'}
function billingSection(){return `<section class="billing-section" id="billing"><div class="row between"><div><h2>Your plan</h2><p class="hint">Everything available in the Bainbot beta.</p></div><span class="tag">Free beta</span></div><div class="billing-current card"><div><small>Current plan</small><h2>Free</h2><span>No credit card required</span></div><div class="billing-current-details"><div><span>Subscription</span><strong>Free during beta</strong></div><div><span>Next payment</span><strong>No payment scheduled</strong></div></div></div><p class="hint">Usage limits apply to keep the beta available for everyone. Connected tools and AI features depend on the workspace configuration.</p></section>`}
function profile(){return `<div class="content">${intro('Profile & team','Manage your profile, team, and free plan.')}<div class="split"><form id="profile-form" class="card stack"><h2>Your profile</h2>${mode==='api'?`<p class="hint">AI provider: ${serverStatus.llm_configured?'Configured · Send a chat message to test':'Not configured · Set the LLM environment variables'}</p>`:''}<label>Full name<input name="name" value="${esc(state.me.name)}" required maxlength="80"></label><label>Email<input value="${esc(state.me.email)}" readonly></label><div class="row between"><span class="pill">${esc(state.me.role)}</span><button class="primary">Save profile</button></div></form><div class="card"><h2>Access levels</h2><p class="muted" style="font-size:12px;margin:15px 0"><strong>Owner</strong> manages agents, people and permissions.</p><p class="muted" style="font-size:12px;margin:15px 0"><strong>Operator</strong> chats and reviews work for assigned agents.</p><p class="muted" style="font-size:12px;margin:15px 0"><strong>Viewer</strong> can read assigned agents and their work.</p>${mode==='api'?'<button onclick="logout()">Sign out</button>':'<div class="auth-preview-links"><span class="tag">Demo changes stay in this browser</span><a href="/login">Login</a><a href="/register">Register</a></div>'}</div></div>${owner()?`<div class="card" style="margin-top:25px"><div class="row between"><div><h2>Team members</h2><small>Choose which agents each member can access.</small></div><button class="primary" onclick="inviteDialog()">+ Add member</button></div><div class="table-wrap"><table><thead><tr><th>Member</th><th>Workspace role</th><th>Agent access</th><th></th></tr></thead><tbody>${state.users.map(u=>`<tr><td><strong>${esc(u.name)}</strong><br><small>${esc(u.email)}</small></td><td>${esc(u.role)}</td><td>${u.role==='owner'?'All agents':state.grants.filter(g=>g.user_id===u.id).length+' assigned'}</td><td>${u.role==='owner'?'<span class="tag">You</span>':`<button onclick="permissions('${u.id}')">Manage access</button>`}</td></tr>`).join('')}</tbody></table></div></div>`:''}${owner()?billingSection():''}</div>`}
function render(){stopVoice();if(!state)return;$('#app').innerHTML=shell(page==='overview'?workspaceOverview():page==='create'?create():page==='agent'?agentProfile():page==='connections'?connections():page==='profile'?profile():chat());bind();if($('#teammate-search'))$('#teammate-search').oninput=e=>document.querySelectorAll('.agent-nav').forEach(n=>n.hidden=!n.dataset.name.includes(e.target.value.toLowerCase()));if(page==='agent'&&sessionStorage.getItem('focus-agent-edit')){sessionStorage.removeItem('focus-agent-edit');$('[name=name]')?.focus()}if(tab==='chat'&&$('.chat-body'))$('.chat-body').scrollTop=$('.chat-body').scrollHeight}
function dialog(html){$('#modal').innerHTML=`<button class="bare" style="float:right" onclick="$('#modal').close()" aria-label="Close dialog">${uiIcon('close')}</button>${html}`;$('#modal').showModal()}
function prefill(text){const field=$('[name=message]');field.value=text;chatDraft(aid).text=text;field.focus()}
function theme(){document.body.classList.toggle('dark');localStorage.setItem('bainbot-theme',document.body.classList.contains('dark')?'dark':'light')}
function useTemplate(i,el){document.querySelectorAll('.template').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');const f=$('#agent-form');['name','role','instructions'].forEach((k,n)=>f.elements[k].value=templates[i][n]);f.elements.avatar.value=i}
function agentData(form,a={}){const d=Object.fromEntries(new FormData(form));const action_permissions={};for(const [key] of actionTypes){action_permissions[key]=d['policy_'+key]||permissionFor(a,key);delete d['policy_'+key]}d.action_permissions=action_permissions;return {...a,...d,avatar:Number(d.avatar??a.avatar??0),status:a.status||'active',reports_to:d.reports_to||a.reports_to||'owner',approval_mode:d.approval_mode||a.approval_mode||'approval'}}
function bind(){const composer=$('#chat-form textarea');if(composer){composer.oninput=()=>{chatDraft(aid).text=composer.value;composer.style.height='auto';composer.style.height=Math.min(composer.scrollHeight,160)+'px'};composer.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();const send=$('#chat-form .send-button');if(send&&!send.disabled)$('#chat-form').requestSubmit(send)}}}const on=(s,fn)=>{if($(s))$(s).onsubmit=async e=>{e.preventDefault();const b=e.submitter;if(b)b.disabled=true;try{await fn(e.target)}catch(err){toast(err.message)}finally{if(b)b.disabled=false}}};on('#agent-form',async f=>{const a=agentData(f);if(mode==='api'){a.id=(await api('/agents',a)).id}else{a.id=crypto.randomUUID();state.agents.push(a)}await refresh();navigate('/agent?id='+encodeURIComponent(a.id));toast('Agent created')});on('#edit-agent-form',async f=>{const a=state.agents.find(a=>a.id===aid),d=agentData(f,a);if(!validManager(d.reports_to,a.id))throw Error('Choose a manager outside this agent’s reporting chain');if(mode==='api')await api('/agents/'+aid,d,'PUT');else Object.assign(a,d);await refresh();toast('Agent updated')});on('#profile-form',async f=>{const name=f.elements.name.value.trim();if(!name)throw Error('Please enter your name');if(mode==='api')await api('/profile',{name},'PUT');else{state.me.name=name;state.users.find(u=>u.id===state.me.id).name=name}await refresh();toast('Profile saved')});on('#chat-form',sendChat);if($('#connection-search'))$('#connection-search').oninput=e=>$('#connection-grid').innerHTML=connectionCards(e.target.value)}
async function toggleAgent(){try{let a=state.agents.find(a=>a.id===aid),d={...a,status:a.status==='active'?'paused':'active'};if(mode==='api')await api('/agents/'+aid,d,'PUT');else Object.assign(a,d);await refresh()}catch(e){toast(e.message)}}
function review(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;const agent=state.agents.find(a=>a.id===t.agent_id);dialog(`<div class="task-detail-heading">${statusBadge(t)}${t.sample?'<span class="sample-caption">Sample task</span>':''}<h2>${esc(t.title)}</h2><p>${esc(agent?.name||'Agent')} · Created ${taskDate(t.created)}</p></div><div class="detail-section"><h3>Task brief</h3><p>${esc(t.summary||t.title)}</p></div>${t.steps?.length?`<div class="detail-section"><h3>Steps</h3>${t.steps.map(step=>`<div class="task-step"><span class="step-marker ${step.status==='done'?'done':''}">${step.status==='done'?uiIcon('check'):''}</span><span>${esc(step.title)}</span><small>${step.status==='done'?'Done':'Waiting'}</small></div>`).join('')}</div>`:''}<div class="detail-section"><h3>${t.status==='failed'?'Issue':t.status==='completed'?'Result':'Draft / output'}</h3><div class="draft">${esc(t.content||'No output yet.')}</div></div><div class="detail-section"><h3>Activity</h3><div class="task-step"><span class="activity-dot"></span><span>Task created</span><small>${taskDate(t.created)}</small></div>${t.started?`<div class="task-step"><span class="activity-dot"></span><span>Work started</span><small>${taskDate(t.started)}</small></div>`:''}<div class="task-step"><span class="activity-dot"></span><span>${esc(taskStatuses[t.status]?.[0]||t.status)}</span><small>${t.finished?taskDate(t.finished):'Current status'}</small></div></div><p class="hint">${t.sample?'Sample data only. No real work has been performed.':'Approving a draft does not execute an external action.'}</p>${t.status==='pending'&&canOperate(t.agent_id)?`<div class="task-detail-actions"><button onclick="decide('${id}','rejected')">Hold back</button><button class="primary" onclick="decide('${id}','approved')">Approve draft</button></div>`:''}`)}
async function decide(id,status){try{if(mode==='api')await api('/tasks/'+id+'/decision',{status});else state.tasks.find(t=>t.id===id).status=status;$('#modal').close();await refresh();toast(status==='approved'?'Draft approved. Nothing was sent.':'Draft held back.')}catch(e){toast(e.message)}}
function connectionInfo(name){dialog(`<div class="connection-dialog-head"><span class="logo">${platformIcon(name)}</span><div><h2>${esc(name)}</h2><small>App connection</small></div></div><div class="notice">Not available yet</div><p>Once available, you’ll be able to connect your ${esc(name)} account and choose what your agents can access.</p><p class="hint">This preview does not connect accounts or collect credentials.</p><button class="primary" onclick="$('#modal').close()">Done</button>`)}
function grantFields(uid){return state.agents.map(a=>{let g=state.grants.find(g=>g.user_id===uid&&g.agent_id===a.id);return `<div class="permission"><span>${esc(a.name)}</span><select aria-label="Access to ${esc(a.name)}" data-grant="${a.id}"><option value="none">No access</option><option value="viewer" ${g?.permission==='viewer'?'selected':''}>Viewer</option><option value="operator" ${g?.permission==='operator'?'selected':''}>Operator</option></select></div>`}).join('')}
function readGrants(){return [...$('#modal').querySelectorAll('[data-grant]')].filter(x=>x.value!=='none').map(x=>({agent_id:x.dataset.grant,permission:x.value}))}
function inviteDialog(){dialog(`<h2>Add a workspace member</h2><form id="invite-form" class="stack"><label>Email address<input name="email" type="email" placeholder="teammate@company.com" required></label><div><h3>Agent access</h3>${grantFields('new')}</div><small>${mode==='demo'?'Demo: adds a sample member locally.':'Creates a one-day invitation link. No email is sent.'}</small><button class="primary">${mode==='demo'?'Add demo member':'Create invitation link'}</button></form>`);$('#invite-form').onsubmit=async e=>{e.preventDefault();try{let email=e.target.elements.email.value,grants=readGrants();if(mode==='api'){let r=await api('/invites',{email,grants});dialog(`<h2>Invitation ready</h2><p>Share this link with ${esc(email)}. It expires in 24 hours.</p><textarea readonly aria-label="Invitation link">${esc(location.origin+'/join?token='+encodeURIComponent(r.token))}</textarea><small>No email has been sent.</small>`)}else{if(state.users.some(u=>u.email===email))throw Error('This member already exists');let id=crypto.randomUUID();state.users.push({id,name:email.split('@')[0],email,role:'member'});state.grants.push(...grants.map(g=>({...g,user_id:id})));$('#modal').close()}await refresh()}catch(e){toast(e.message)}}}
function permissions(uid){dialog(`<h2>Manage agent access</h2><form id="permissions-form" class="stack"><div>${grantFields(uid)}</div><button class="primary">Save access</button></form>`);$('#permissions-form').onsubmit=async e=>{e.preventDefault();try{let grants=readGrants();if(mode==='api')await api('/users/'+uid+'/grants',{grants},'PUT');else state.grants=[...state.grants.filter(g=>g.user_id!==uid),...grants.map(g=>({...g,user_id:uid}))];$('#modal').close();await refresh();toast('Access updated')}catch(e){toast(e.message)}}}
function clearPrivateState(){stopVoice();state=null;chatDrafts.clear();busy=false;$('#modal')?.close();localStorage.removeItem('bainbot-workfolk-reference-v2')}
async function logout(){try{await api('/logout',{});clearPrivateState();location.replace('/login')}catch(e){toast('Could not sign out. Please retry.')}}
let serverStatus={};
async function start(){normalizeWorkspaceURL();
 document.body.classList.remove('dark');mode='api';
 try{serverStatus=await api('/status');if(serverStatus.mode!=='api')throw Error('Backend is not available. Start the Python server.')}catch(e){$('#app').innerHTML=`<div class="auth-screen" style="display:block;padding:40px"><h1>Unable to connect</h1><p style="margin:20px 0">${esc(e.message)} This build requires its Python backend; it does not switch to demo data.</p><button onclick="location.reload()">Retry connection</button></div>`;return}
 authSetupAvailable=true;
 if(location.pathname.replace(/\/$/,'')==='/reset-password')return resetPage();
 if(location.pathname==='/join')return auth(false,new URLSearchParams(location.search).get('token')||'');
 if(location.pathname.replace(/\/$/,'')==='/verify-email')return verificationPage();
 if(authRoute())return authPage(authPath());
 try{state=await api('/state')}catch(e){history.replaceState(null,'','/login');return auth(false)}
 route();
}
window.addEventListener('hashchange',()=>{if(state||authRoute()){tab='chat';route()}});

const chatDrafts=new Map();
let voiceSession=null;
function chatDraft(id){if(!chatDrafts.has(id))chatDrafts.set(id,{text:'',files:[],research:false,workflow:true});return chatDrafts.get(id)}
function chatIcon(type){return `<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${type==='mic'?'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/>':'<path d="m21 11-9 9a6 6 0 0 1-8.5-8.5l9-9a4 4 0 0 1 5.7 5.7l-9 9a2 2 0 0 1-2.8-2.8l8.5-8.5"/>'}</svg>`}
function fileSize(n){return n>=1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB'}
function attachmentMarkup(files){return files?.length?`<div class="sent-attachments">${files.map(f=>`<span class="sent-file">${uiIcon('file')}<span>${esc(f.name)}<small>${fileSize(f.size)} · Preview attachment</small></span></span>`).join('')}</div>`:''}
function chatComposer(a){const d=chatDraft(a.id),disabled=busy||!canOperate(a.id)||a.status==='paused';return `<form class="composer enhanced-composer" id="chat-form"><div id="attachment-list" class="attachment-list">${pendingFiles(a.id)}</div><textarea aria-label="Message ${esc(a.name)}" name="message" placeholder="Message ${esc(a.name)}…" maxlength="10000" ${disabled?'disabled':''}>${esc(d.text)}</textarea><div class="composer-tools"><div class="composer-actions"><input type="file" id="chat-files" multiple hidden onchange="selectChatFiles(this)"><button type="button" class="composer-tool" aria-label="Add files" title="File analysis is coming soon" disabled>${chatIcon('file')}</button><button type="button" id="voice-button" class="composer-tool" aria-label="Start voice typing" title="Voice typing" aria-pressed="false" onclick="toggleVoice()" ${disabled?'disabled':''}>${chatIcon('mic')}</button><select class="workflow-mode" aria-label="Task mode" onchange="chatDraft(aid).research=this.value==='search';chatDraft(aid).workflow=this.value==='workflow'" ${disabled?'disabled':''}><option value="workflow" ${d.workflow?'selected':''}>Agent workflow</option><option value="chat" ${!d.workflow&&!d.research?'selected':''}>Chat only</option><option value="search" ${d.research?'selected':''} ${!state.capabilities?.search?'disabled':''}>Search only</option></select><span id="voice-status" class="composer-hint" role="status">One prompt, research and writing</span></div><button type="submit" class="send-button" aria-label="Send message" ${disabled?'disabled':''}>${busy?'<span class="loading-dot"></span>':uiIcon('arrow')}</button></div><p id="attachment-note" class="attachment-note" ${d.files.length?'':'hidden'}>Preview only · Files are not uploaded or analyzed.</p></form>`}
function pendingFiles(id){return chatDraft(id).files.map((f,i)=>`<span class="attachment-chip">${uiIcon('file')}<span><strong>${esc(f.name)}</strong><small>${fileSize(f.size)}</small></span><button type="button" aria-label="Remove ${esc(f.name)}" onclick="removeChatFile(${i})">${uiIcon('close')}</button></span>`).join('')}
function updateFiles(){const list=$('#attachment-list');if(list)list.innerHTML=pendingFiles(aid);const note=$('#attachment-note');if(note)note.hidden=!chatDraft(aid).files.length}
function selectChatFiles(input){const d=chatDraft(aid);for(const f of input.files){if(d.files.length>=5){toast('Attach up to 5 files per message.');break}if(f.size>10*1024*1024){toast(f.name+' exceeds the 10 MB limit.');continue}if(!d.files.some(x=>x.name===f.name&&x.size===f.size))d.files.push(f)}input.value='';updateFiles()}
function removeChatFile(index){chatDraft(aid).files.splice(index,1);updateFiles()}
function stopVoice(){if(voiceSession){const old=voiceSession;voiceSession=null;old.abort()}}
function toggleVoice(){if(voiceSession){voiceSession.stop();return}const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){toast('Voice typing is not supported in this browser. Try Chrome or Edge, or use your keyboard microphone.');return}const a=state.agents.find(a=>a.id===aid);if(busy||!canOperate(aid)||a?.status==='paused')return;const id=aid,field=$('[name=message]'),button=$('#voice-button'),label=$('#voice-status'),recognition=new Recognition();let finalText=field.value;recognition.lang=navigator.language||'en-US';recognition.continuous=true;recognition.interimResults=true;voiceSession=recognition;button.setAttribute('aria-pressed','true');button.setAttribute('aria-label','Stop voice typing');label.textContent='Listening… Click the microphone to stop';recognition.onresult=e=>{if(voiceSession!==recognition)return;let interim='';for(let i=e.resultIndex;i<e.results.length;i++){if(e.results[i].isFinal)finalText+=(finalText?' ':'')+e.results[i][0].transcript;else interim+=e.results[i][0].transcript}field.value=(finalText+(interim?' '+interim:'')).slice(0,10000);chatDraft(id).text=field.value;field.style.height=Math.min(field.scrollHeight,160)+'px'};recognition.onerror=e=>{label.textContent=e.error==='not-allowed'?'Microphone access denied. Allow it in browser settings.':e.error==='no-speech'?'No speech detected. Try again.':'Voice typing unavailable. Please try again.'};recognition.onend=()=>{if(voiceSession===recognition)voiceSession=null;button.setAttribute('aria-pressed','false');button.setAttribute('aria-label','Start voice typing');if(label.textContent.startsWith('Listening'))label.textContent='Voice typing stopped · Review before sending'};try{recognition.start()}catch{voiceSession=null;button.setAttribute('aria-pressed','false');label.textContent='Could not start voice typing. Please try again.'}}
async function sendChat(f){const id=aid,d=chatDraft(id),content=f.elements.message.value.trim(),files=d.files.map(x=>({name:x.name,size:x.size,type:x.type}));if(!content&&!files.length)return;const a=state.agents.find(a=>a.id===id);if(busy||!canOperate(id)||a.status==='paused')return;if(effectiveRule(a,d.research?'research':'draft')==='block')throw Error('This action is disabled for this agent');if(d.research&&content.length>400)throw Error('Keep your web search under 400 characters.');if((d.research||(d.workflow&&state.capabilities?.search))&&effectiveRule(a,'research')==='approval'&&!window.confirm('Allow public web research for this task? Relevant search queries will be sent to your configured search provider.'))return;if(mode==='api'&&files.length)throw Error('File processing is not connected yet. Remove the attachments to send a text message.');d.text=content;stopVoice();busy=true;render();try{if(mode==='api')await api('/agents/'+id+(d.workflow?'/workflow':d.research?'/research':'/messages'),{content,...(d.research||d.workflow?{confirmed:true}:{})});else{state.messages.push({agent_id:id,role:'user',content,attachments:files},{agent_id:id,role:'assistant',content:files.length?'Your message and attachment names are saved in this preview. Files have not been uploaded or read.\n\nThis is a demo. No AI response or external action has run.':'Your request is saved as a sample draft. Open Tasks to review it.\n\nThis is a demo. No AI response or external action has run.'});state.tasks.unshift({id:crypto.randomUUID(),agent_id:id,title:(content||files.map(x=>x.name).join(', ')).slice(0,100),content:'DEMO BRIEF — not AI-generated output\n\n'+content+(files.length?'\n\nPreview attachments (not uploaded): '+files.map(x=>x.name).join(', '):''),status:effectiveRule(a,'draft')==='allow'?'ready':'pending',created:Date.now()/1000})}await refresh();d.text='';d.files=[]}catch(error){try{await refresh()}catch{}throw error}finally{busy=false;render()}}
window.addEventListener('pagehide',stopVoice);

start();

function workspacePath(){const p=location.pathname.replace(/^\/+|\/+$/g,'');return ['app','agent','create','overview','connections','profile'].includes(p)?p:''}
function normalizeWorkspaceURL(){const old=location.hash.slice(1);if(old){const [name,id,view]=old.split('/');if(['app','agent','create','overview','connections','profile','login','register','forgot-password','join'].includes(name)){let target='/'+name;if(id&&['app','agent','join'].includes(name))target+='?'+({app:'agent',agent:'id',join:'token'}[name])+'='+encodeURIComponent(id);if(name==='app'&&view==='tasks')target+='&tab=tasks';history.replaceState(null,'',target)}}const path=workspacePath();if(path&&location.pathname!=='/'+path)history.replaceState(null,'','/'+path+location.search)}
function navigate(url){history.pushState(null,'',url);route()}
window.addEventListener('popstate',()=>{route()});
document.addEventListener('click',event=>{const link=event.target.closest?.('a[href]');if(!link||event.defaultPrevented||event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey||link.target||link.hasAttribute('download'))return;const url=new URL(link.href,location.href);if(url.origin!==location.origin||!['/app','/agent','/create','/overview','/connections','/profile'].includes(url.pathname)||url.hash)return;event.preventDefault();navigate(url.pathname+url.search)});

window.addEventListener('pageshow',event=>{if(event.persisted)location.reload()});
